package main
use fmt;
enum State { Count(int), Other(int), }
func slot(v &mut State)&mut int { match &mut *v {State::Count(p)=>{return p},_=>{panic("wrong variant")},};panic("unreachable") }
func read(v State)int{return match v{State::Count(n)=>n,State::Other(n)=>n}}
func main(){v:=State::Count(1);p:=slot(&mut v);v=State::Other(8);if *p!=1{panic("old object changed")};*p=11;if read(v)!=8{panic("old slot retargeted")};v=State::Count(13);fmt::Println(*p,read(v))}

package main
use fmt;
func slot(v &mut Result[int,int])&mut int { match &mut *v {Result::Ok(p)=>{return p},Result::Err(_)=>{panic("wrong variant")},};panic("unreachable") }
func read(v Result[int,int])int{return match v{Result::Ok(n)=>n,Result::Err(n)=>n}}
func main(){v:=Result[int,int]::Ok(1);p:=slot(&mut v);v=Result[int,int]::Err(8);if *p!=0{panic("slot not reset")};*p=11;if read(v)!=8{panic("old slot retargeted")};v=Result[int,int]::Ok(13);fmt::Println(*p,read(v))}

